-- HOME For You proof only: six general messages and four contextual messages.
begin;
create table if not exists public.home_inspiration_messages (
 message_id text primary key, message_text text not null check(length(trim(message_text))>0),
 theme text not null check(theme in ('CONFIDENCE','SMALL_STEPS','SELF_TRUST','CONNECTION','FLEXIBILITY','LIFE_BEYOND_CELIAC')),
 message_type text not null check(message_type in ('DAILY_GENERAL','CONTEXTUAL')),
 trigger_key text, source_basis jsonb not null check(jsonb_typeof(source_basis)='array'),
 review_status text not null default 'needs_review' check(review_status in ('approved','needs_review','hidden')),
 expert_reviewed boolean not null default false, active boolean not null default true,
 content_version text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check((message_type='DAILY_GENERAL' and trigger_key is null) or (message_type='CONTEXTUAL' and trigger_key is not null and trigger_key in ('UPCOMING_CDAY','HARD_ACTION_DONE','ACTION_RESCHEDULED','NO_UPCOMING_CDAY','ACTION_NOT_NEEDED','EXPLORE_COMPLETED','PLAN_FINALIZED','SUPPORT_USED')))
);
alter table public.home_inspiration_messages enable row level security;
revoke all on public.home_inspiration_messages from anon, authenticated;
grant select on public.home_inspiration_messages to anon, authenticated;
drop policy if exists inspiration_approved_read on public.home_inspiration_messages;
create policy inspiration_approved_read on public.home_inspiration_messages for select to anon, authenticated using(active and review_status='approved');
create or replace function public.home_inspiration_touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at:=now();return new;end $$;
drop trigger if exists home_inspiration_updated_at on public.home_inspiration_messages;
create trigger home_inspiration_updated_at before update on public.home_inspiration_messages for each row execute function public.home_inspiration_touch_updated_at();
comment on table public.home_inspiration_messages is 'Original Plan My C-Day inspiration. source_basis describes supporting themes, not message authorship. No XP or Community content.';
lock table public.home_inspiration_messages in share row exclusive mode;
do $import$ declare wanted jsonb; incoming public.home_inspiration_messages%rowtype; current_row public.home_inspiration_messages%rowtype;
begin
for wanted in select value from jsonb_array_elements($records$[{"message_id": "INS_CONF_001", "message_text": "You know more than you think you do.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_001", "message_text": "One small step still counts.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_001", "message_text": "You can ask questions and make the choice that feels right for you.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_001", "message_text": "You deserve to be part of the plan.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_001", "message_text": "Plans can change. Adjusting is part of the skill.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_001", "message_text": "Celiac is part of your day. It doesn't have to be the whole day.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_UPCOMING_001", "message_text": "A little planning now can leave more room for fun later.", "theme": "SMALL_STEPS", "message_type": "CONTEXTUAL", "trigger_key": "UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_HARD_DONE_001", "message_text": "You did something that felt challenging. Notice that.", "theme": "CONFIDENCE", "message_type": "CONTEXTUAL", "trigger_key": "HARD_ACTION_DONE", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_RESCHEDULE_001", "message_text": "Plans can change. Adjusting the plan is part of the skill.", "theme": "FLEXIBILITY", "message_type": "CONTEXTUAL", "trigger_key": "ACTION_RESCHEDULED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_NO_EVENT_001", "message_text": "Today doesn't have to be about celiac. Go do something you love.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "CONTEXTUAL", "trigger_key": "NO_UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}]$records$::jsonb) loop
 select * into incoming from jsonb_populate_record(null::public.home_inspiration_messages,wanted);
 select * into current_row from public.home_inspiration_messages where message_id=incoming.message_id;
 if found then
  if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then raise exception 'Message % differs; no changes made.',incoming.message_id;end if;
 else
 insert into public.home_inspiration_messages(message_id,message_text,theme,message_type,trigger_key,source_basis,review_status,expert_reviewed,active,content_version) values (incoming.message_id,incoming.message_text,incoming.theme,incoming.message_type,incoming.trigger_key,incoming.source_basis,incoming.review_status,incoming.expert_reviewed,incoming.active,incoming.content_version);
 end if;
end loop;
end $import$;
commit;
with expected as(select value as record from jsonb_array_elements($records$[{"message_id": "INS_CONF_001", "message_text": "You know more than you think you do.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_001", "message_text": "One small step still counts.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_001", "message_text": "You can ask questions and make the choice that feels right for you.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_001", "message_text": "You deserve to be part of the plan.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_001", "message_text": "Plans can change. Adjusting is part of the skill.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_001", "message_text": "Celiac is part of your day. It doesn't have to be the whole day.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_UPCOMING_001", "message_text": "A little planning now can leave more room for fun later.", "theme": "SMALL_STEPS", "message_type": "CONTEXTUAL", "trigger_key": "UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_HARD_DONE_001", "message_text": "You did something that felt challenging. Notice that.", "theme": "CONFIDENCE", "message_type": "CONTEXTUAL", "trigger_key": "HARD_ACTION_DONE", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_RESCHEDULE_001", "message_text": "Plans can change. Adjusting the plan is part of the skill.", "theme": "FLEXIBILITY", "message_type": "CONTEXTUAL", "trigger_key": "ACTION_RESCHEDULED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_NO_EVENT_001", "message_text": "Today doesn't have to be about celiac. Go do something you love.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "CONTEXTUAL", "trigger_key": "NO_UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}]$records$::jsonb))
select x.record->>'message_id' message_id,e.message_type,e.theme,e.trigger_key,
case when e.message_id is not null and not exists(select 1 from jsonb_each(x.record) f where to_jsonb(e)->f.key is distinct from f.value) then 'PASS' else 'CHECK MISSING OR CHANGED FIELDS' end qa_result
from expected x left join public.home_inspiration_messages e on e.message_id=x.record->>'message_id' order by message_id;
